package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.*;
import java.io.IOException;
import java.io.Reader;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonTreeReader_skipValue_TriageGen2Test {

    private JsonTreeReader jsonTreeReader;

    @Before
    public void setup() {
        JsonElement element = new JsonElement();
        jsonTreeReader = new JsonTreeReader(element);
    }

    @Test
    public void testSkipValue_peekIsNAME() throws IOException {
        jsonTreeReader.stackSize = 2;
        jsonTreeReader.pathNames[1] = "name";
        jsonTreeReader.pathIndices[1] = 0;
        jsonTreeReader.peek = JsonToken.NAME;
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[1]);
        assertEquals(1, jsonTreeReader.pathIndices[1]);
    }

    @Test
    public void testSkipValue_peekIsNotNAME() throws IOException {
        jsonTreeReader.stackSize = 1;
        jsonTreeReader.pathNames[0] = "name";
        jsonTreeReader.pathIndices[0] = 0;
        jsonTreeReader.peek = JsonToken.END_ARRAY;
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[0]);
        assertEquals(1, jsonTreeReader.pathIndices[0]);
    }

    @Test
    public void testSkipValue_popStack() throws IOException {
        jsonTreeReader.stackSize = 1;
        jsonTreeReader.pathNames[0] = "name";
        jsonTreeReader.pathIndices[0] = 0;
        jsonTreeReader.peek = JsonToken.END_ARRAY;
        jsonTreeReader.popStack();
        jsonTreeReader.skipValue();
        assertNull(jsonTreeReader.pathNames[0]);
        assertEquals(0, jsonTreeReader.pathIndices[0]);
    }

    @Test
    public void testSkipValue_pathNamesIsNull() throws IOException {
        jsonTreeReader.stackSize = 1;
        jsonTreeReader.pathNames[0] = null;
        jsonTreeReader.pathIndices[0] = 0;
        jsonTreeReader.peek = JsonToken.END_ARRAY;
        jsonTreeReader.skipValue();
        assertNull(jsonTreeReader.pathNames[0]);
        assertEquals(0, jsonTreeReader.pathIndices[0]);
    }

    @Test
    public void testSkipValue_pathNamesIsNotInitialized() throws IOException {
        jsonTreeReader.stackSize = 1;
        jsonTreeReader.pathNames = null;
        jsonTreeReader.pathIndices[0] = 0;
        jsonTreeReader.peek = JsonToken.END_ARRAY;
        jsonTreeReader.skipValue();
        assertNull(jsonTreeReader.pathNames);
        assertEquals(0, jsonTreeReader.pathIndices[0]);
    }

    @Test(expected = IOException.class)
    public void testSkipValue_throwsIOException() throws IOException {
        jsonTreeReader.stackSize = 1;
        jsonTreeReader.pathNames[0] = "name";
        jsonTreeReader.pathIndices[0] = 0;
        jsonTreeReader.peek = JsonToken.END_ARRAY;
        jsonTreeReader.skipValue();
        throw new IOException();
    }
}
